/* GENERATED by night/tools/phloemA/gen_phloem_quiz_site.py from the Sugar on the move plates (p_source.js, p_sieve.js,
   quiz.js): do not edit by hand. The phloem Test yourself bank for the site wide #/quiz page (module "phloem").
   Hook for app.js (main page owner), next to the light and journey lines:
   var PQ=window.WP_QUIZ_PHLOEM_BANK; if(PQ&&PQ.items&&!Q._phloem){Q._phloem=1; PQ.items.forEach(function(i){Q.items.push(i)})} */
window.WP_QUIZ_PHLOEM_BANK = {"items": [{"id": "src-k-types", "t": 1, "plate": "source", "b": "MEASURED", "src": ["10.1073/pnas.0902279106"], "q": "Which of these is NOT one of the three ways leaves load sugar into the phloem?", "o": [["Pumping sugar up from the roots in the xylem", "Right. The three are active loading through the cell wall, passive loading through plasmodesmata, and the polymer trap."], ["Passive loading through plasmodesmata", "That is one of the three, common in trees."], ["The polymer trap", "That is one of the three: sucrose is built into raffinose and stachyose in intermediary cells."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-k-sweet", "t": 1, "plate": "source", "b": "MEASURED", "src": ["10.1126/science.1213351"], "q": "In active (apoplastic) loading, which pair of proteins moves sucrose out of one cell and into the companion cell?", "o": [["SWEET out into the cell wall, then SUT in with a proton", "Right. Shown with sucrose sensors and mutants in Arabidopsis (Chen et al. 2012)."], ["Aquaporins out, then aquaporins in", "Aquaporins carry water, not sucrose."], ["Rubisco out, then SWEET in", "Rubisco fixes CO₂ in the chloroplast; it does not move sugar."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-k-trap", "t": 1, "plate": "source", "b": "MEASURED", "src": ["10.1073/pnas.0902279106"], "q": "In the polymer trap, what does the intermediary cell build sucrose into?", "o": [["Raffinose and stachyose, which are too big to diffuse back", "Right. That traps sugar in the phloem without a transporter."], ["Starch, stored for the night", "Starch is stored in chloroplasts, not built in the phloem to trap sugar."], ["Sorbitol", "Sorbitol is a separate transport sugar of Rosaceae, made in the leaf."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-k-trees", "t": 1, "plate": "source", "b": "MEASURED", "src": ["10.1007/s00709-010-0240-7"], "q": "Which kind of plant most often loads passively, through plasmodesmata?", "o": [["Trees", "Right. Passive loading goes with the tree growth form; active loading with herbs."], ["Herbs", "Herbs are mostly active, apoplastic loaders."], ["Neither, every plant loads actively", "Passive loading is widespread, especially in trees."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-k-sorb", "t": 1, "plate": "source", "b": "MEASURED", "src": ["10.1104/pp.102.016725"], "q": "Almond, peach and apple export a second sugar besides sucrose. Which?", "o": [["Sorbitol", "Right. In many Rosaceae sorbitol is a primary product of photosynthesis and the main transport sugar."], ["Glucose", "Glucose is not the main transport form in these trees."], ["Raffinose", "Raffinose is the sugar of polymer trap loaders such as melon type plants."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-k-pd", "t": 1, "plate": "source", "b": "MEASURED", "src": ["10.1073/pnas.0902279106"], "q": "In passive loading, sugar reaches the sieve element by:", "o": [["Diffusing through plasmodesmata, the channels that join neighbouring cells", "Right. It stays inside the cells the whole way."], ["Crossing the cell wall by SWEET", "That is the active route."], ["Riding in the xylem", "The xylem carries water up; sugar enters the phloem."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-u-uphill", "t": 2, "plate": "source", "b": "ILLUSTRATIVE", "src": ["10.1007/s00425-007-0682-0"], "q": "A leaf has 1.8 % sugar in its mesophyll cytosol and 18 % in its sieve elements. Which loading types could do that?", "o": [["Active loading (or a trap for total sugar), not passive diffusion", "Right. Ten fold uphill needs a transporter or a trap. Measured ratios run 2 to 40 fold across four species."], ["Passive loading", "Diffusion cannot run uphill."], ["Any type, ratios do not depend on loading", "The ratio is exactly what separates the types."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-u-pi", "t": 2, "plate": "source", "b": "DERIVED", "src": ["10.1111/pce.12004"], "q": "Sap at 18 % sucrose has Π ≈ 1.59 MPa. The xylem beside it is at −0.50 MPa. What turgor does the model give the sieve element?", "o": [["About 1.09 MPa", "Right. P = Ψx + Π = −0.50 + 1.59. Morning glory measured 1.08 MPa."], ["About 2.09 MPa", "The xylem potential is negative; it lowers the turgor."], ["About 0.50 MPa", "That ignores the osmotic pressure of the sugar."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-u-sorb", "t": 2, "plate": "source", "b": "DERIVED", "src": [], "q": "Sorbitol weighs 182 g mol⁻¹ and sucrose 342 g mol⁻¹. At the same grams of sugar per litre of sap, how does the osmotic pressure compare?", "o": [["Sorbitol gives about 1.9 times more", "Right. 342 ÷ 182 = 1.88: twice the particles for the same mass, and Π counts particles."], ["The same, because the mass is the same", "Osmotic pressure counts particles, not grams."], ["Sucrose gives more, because it is bigger", "Bigger molecules mean fewer particles per gram."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-u-poplar", "t": 2, "plate": "source", "b": "MEASURED", "src": ["10.1104/pp.114.245845"], "q": "Poplar and alfalfa were given an enzyme that destroys sucrose in the cell walls. Poplar grew normally; alfalfa could not load. What follows?", "o": [["Poplar loads through plasmodesmata; alfalfa needs the cell wall route", "Right. If sugar never enters the wall, destroying it there does nothing."], ["Poplar does not export sugar", "It grew normally, so it exported."], ["The enzyme did not work in poplar", "The comparison with alfalfa is the control for that."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-u-sweet", "t": 2, "plate": "source", "b": "MEASURED", "src": ["10.1126/science.1213351"], "q": "An Arabidopsis plant lacks both SWEET11 and SWEET12. Which step of active loading fails?", "o": [["Release of sucrose from the phloem parenchyma into the cell wall", "Right. SUT then has little sucrose to take up; the double mutant is defective in loading."], ["Uptake into the companion cell by SUT", "SUT is still there; its supply in the wall is what is missing."], ["Sugar synthesis in the mesophyll", "Photosynthesis is not what the SWEETs do."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-u-dry", "t": 2, "plate": "source", "b": "MODEL", "src": ["10.1111/pce.12004", "10.7554/eLife.15341"], "q": "Same sap (Π 1.59 MPa), but the xylem dries from −0.50 to −1.00 MPa. Sink turgor is 0.59 MPa. What happens in the model?", "o": [["Source turgor drops to about 0.59 MPa, equal to the sink, and flow stops", "Right. Unless the leaf loads more osmolyte, a drier xylem takes the pressure away."], ["Nothing, the phloem is separate from the xylem", "The sieve tube gets its water from the xylem; that is the coupling."], ["Flow speeds up because the xylem pulls harder", "A stronger pull lowers phloem pressure; it does not push sap."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-q-almond", "t": 3, "plate": "source", "b": "OPEN QUESTION", "src": ["10.1104/pp.108.134791", "10.1007/s00425-007-0682-0"], "q": "A grower’s handout says almond loads sorbitol passively, just like apple. How strong is that claim?", "o": [["Untested: apple loads passively and peach looks mixed, but no almond loading study was found", "Right. Relatives are a hint, not a measurement. Say what was measured, and in which species."], ["Proven, all Rosaceae load the same way", "Apple and peach already differ."], ["Wrong, almond certainly loads actively", "No study supports that either."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-q-silence", "t": 3, "plate": "source", "b": "MEASURED", "src": ["10.1073/pnas.0605873103"], "q": "Silencing sorbitol synthesis in apple cut the leaf sorbitol to sucrose ratio by about 90 %, and the trees survived. Someone concludes sorbitol is unnecessary. Evaluate.", "o": [["Weak: the leaves made more sucrose and starch, fixed less carbon, and the fruit sugar and acid balance changed", "Right. Survival is not the same as no effect; the plant paid for the change."], ["Correct, survival proves it", "The measured costs say otherwise."], ["Correct, because sucrose can do everything sorbitol does", "Assimilation fell, so the swap was not free."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-q-waste", "t": 3, "plate": "source", "b": "MEASURED", "src": ["10.1104/pp.111.184820", "10.1073/pnas.0902279106"], "q": "Trees that load passively keep much more sugar in their leaves than active loaders. Someone calls this a waste. What is the best reply?", "o": [["High leaf sugar is what passive loading requires, and across 45 species it travelled with low hydraulic conductance and high leaf osmolality; a cross species correlation cannot show it is waste or a benefit", "Right. Describe the pattern; test the purpose separately."], ["It is waste, trees are less efficient", "Efficient for what? The comparison does not measure fitness."], ["It cannot be true, sugar is always low in leaves", "Measured leaf transport sugars differed more than 50 fold between types."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-q-chip", "t": 3, "plate": "source", "b": "MODEL", "src": ["10.1038/nplants.2017.32"], "q": "A microfluidic “tree on a chip” loading passively reached about 1 MPa. Does that show tall trees load passively and make enough pressure?", "o": [["No: it shows the physics can work in a device; whether trees do it is still open", "Right. A device value is a MODEL, not a plant measurement."], ["Yes, a chip is a tree", "It mimics a mechanism; it is not a tree."], ["No, 1 MPa is too small for any plant", "Morning glory sieve tubes ran at about 1.08 MPa."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-q-maize", "t": 3, "plate": "source", "b": "MEASURED", "src": ["10.1038/s41477-022-01098-x"], "q": "A maize sut1 mutant exported only about 4 % of the normal leaf carbon, yet kept its phloem pressure near normal by loading more potassium. What does that tell you about pressure flow?", "o": [["Pressure comes from any osmolyte; sugar is the cargo, not the only source of pressure", "Right. Sap speed stayed at 50 to 75 % of wild type, with little sugar in it."], ["Pressure flow is not real", "The pressure was measured and stayed up."], ["Potassium is the main sugar in maize", "Potassium is an ion, not a sugar."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "src-q-why", "t": 3, "plate": "source", "b": "OPEN QUESTION", "src": ["10.1104/pp.108.134791"], "q": "Reidel and colleagues suggested apple moves sorbitol at high concentration to avoid the feedback on photosynthesis that high sucrose would cause. How should you treat that?", "o": [["As the authors’ hypothesis, to be tested, for example by changing leaf sucrose and measuring photosynthesis", "Right. A suggested reason is not a result."], ["As an established fact", "The paper proposes it; it does not prove it."], ["As wrong, sorbitol has no role", "Nothing retrieved shows that either."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#source", "where": "Sugar I, the Source leaf"}, {"id": "sv-k-munch", "t": 1, "plate": "sieve", "b": "MEASURED", "src": ["10.7554/eLife.15341"], "q": "In the Münch model, what drives sap through the sieve tubes?", "o": [["A difference in turgor between source and sink, made by loading and unloading osmolytes", "Right. High pressure where sugar is loaded, lower where it is unloaded."], ["Transpiration pulling the sap up, as in the xylem", "The phloem is pushed, not pulled, and it often runs downward."], ["Molecular motors in the sieve elements", "Sieve elements have no such motors; flow is driven by pressure."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-k-nuc", "t": 1, "plate": "sieve", "b": "MEASURED", "src": ["10.1073/pnas.2112755119"], "q": "What does a mature sieve element lack?", "o": [["A nucleus (and the machinery to make proteins, and Golgi)", "Right. That keeps the lumen open; the companion cell supports it."], ["A plasma membrane", "It keeps its membrane; it must hold pressure and sugar."], ["Cell walls", "It has walls, and sieve plates between elements."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-k-cc", "t": 1, "plate": "sieve", "b": "MEASURED", "src": ["10.1104/pp.106.085803"], "q": "How is a companion cell connected to its sieve element?", "o": [["By pore plasmodesma units, with their endoplasmic reticulum continuous between the two cells", "Right. Measured in tobacco: the strongest coupling of any cell pair tested."], ["Only through the cell wall space", "They share a symplastic connection."], ["They are not connected", "They work as one complex."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-k-callose", "t": 1, "plate": "sieve", "b": "MEASURED", "src": ["10.1105/tpc.109.070094"], "q": "What can close small sieve plate pores within minutes after a sieve tube is injured?", "o": [["Callose", "Right. It is a wound response; it seals the damaged tube."], ["Lignin", "Lignin stiffens xylem walls; it is not the fast plug."], ["Starch", "Starch is a store, not a plug."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-k-mri", "t": 1, "plate": "sieve", "b": "MEASURED", "src": ["10.1111/j.1365-3040.2006.01544.x"], "q": "Flow MRI measured phloem sap speed in poplar, castor bean, tomato and tobacco. About how fast?", "o": [["0.25 to 0.40 mm per second", "Right. Day and night, across the four species."], ["About 1 m per second", "Far too fast for phloem."], ["About 1 mm per day", "Far too slow: that is about a million times slower."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-k-seor", "t": 1, "plate": "sieve", "b": "MEASURED", "src": ["10.1105/tpc.111.093179"], "q": "In living sieve tubes, the SEOR protein meshwork:", "o": [["Lines the walls and does not markedly slow the flow", "Right. Plugs seen in older micrographs were mostly preparation artefacts."], ["Fills the lumen and stops flow", "That is what fixed, damaged tubes looked like."], ["Pumps sugar", "It is a structural protein, not a pump."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-u-hp", "t": 2, "plate": "sieve", "b": "DERIVED", "src": ["10.7554/eLife.15341"], "q": "k = 1 µm², gradient 0.21 MPa m⁻¹, η = 1.7 mPa s. Speed by U = k × gradient ÷ η × 1000 (in µm s⁻¹)?", "o": [["About 124 µm s⁻¹", "Right. Measured: 123 µm s⁻¹. The pressure is enough."], ["About 357 µm s⁻¹", "That multiplies by η instead of dividing."], ["About 0.21 µm s⁻¹", "That leaves out the conductivity and the units."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-u-length", "t": 2, "plate": "sieve", "b": "DERIVED", "src": [], "q": "The same pressure difference must push sap over twice the distance. If nothing else changes, the speed:", "o": [["Halves", "Right. The gradient (ΔP ÷ L) halves, and speed follows the gradient."], ["Doubles", "More distance cannot speed it up."], ["Is unchanged", "Pressure difference is spread over more tube."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-u-plates", "t": 2, "plate": "sieve", "b": "MODEL", "src": ["10.3389/fpls.2012.00151"], "q": "Plates and the open tube each give about half of the resistance. If the plates added nothing, the speed at the same pressure would:", "o": [["About double", "Right. Half the resistance, twice the flow."], ["Rise by 10 %", "Plates are about half the resistance, not a tenth."], ["Not change, plates do not resist", "They do: about half of it."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-u-cmh", "t": 2, "plate": "sieve", "b": "DERIVED", "src": ["10.1093/treephys/tpv020"], "q": "Angiosperm trees move phloem sugar about 56 cm per hour on average. In µm per second that is about:", "o": [["156 µm s⁻¹", "Right. 560,000 µm ÷ 3,600 s."], ["56 µm s⁻¹", "That forgets to convert centimetres to micrometres and hours to seconds."], ["15,600 µm s⁻¹", "One hundred times too fast."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-u-beech", "t": 2, "plate": "sieve", "b": "MEASURED", "src": ["10.1093/treephys/tpy122"], "q": "In mature beech after three dry summers, phloem speed fell from 20.7 to 11.0 cm h⁻¹. By what share?", "o": [["About 47 %", "Right. (20.7 − 11.0) ÷ 20.7 = 0.47; it tracked predawn water potential."], ["About 9.7 %", "That is the difference in cm h⁻¹, not the share."], ["About 88 %", "It roughly halved, not stopped."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-u-range", "t": 2, "plate": "sieve", "b": "DERIVED", "src": ["10.7554/eLife.15341"], "q": "Morning glory: 0.49 MPa available between source and sink, and 0.21 MPa per metre needed for the measured speed. Over about how long a path could that pressure keep the measured speed?", "o": [["About 2.3 m", "Right. 0.49 ÷ 0.21. Longer plants made more pressure and had wider plate pores."], ["About 0.1 m", "That multiplies the two values."], ["Any length", "The gradient falls as the path grows."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-q-plates", "t": 3, "plate": "sieve", "b": "MEASURED", "src": ["10.7554/eLife.15341", "10.3389/fpls.2012.00151"], "q": "Someone argues: sieve plates are barriers, so pressure flow cannot work in tall plants. What do the measurements say?", "o": [["Plates add about half the resistance but do not stop flow, and in 17.5 m vines the plate pores were wider, conductivity 5 to 6 times higher and source turgor more than 2.2 MPa in some vines", "Right. Plants tune the path to its length."], ["They are right, tall plants use another mechanism", "The measured pressures and speeds fit pressure flow."], ["Plates add no resistance at all", "They add about half."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-q-nacre", "t": 3, "plate": "sieve", "b": "MEASURED", "src": ["10.1111/tpj.14665"], "q": "Thick “nacreous” walls appear in over 90 % of sieve elements in standard sections, but not in living, transporting tubes, and a puncture makes them in under a minute. What should you conclude?", "o": [["They are preparation artefacts; images of cut tissue need checking against living tissue", "Right. The method made the structure."], ["They are a real feature that live imaging misses", "Puncture creating them argues otherwise."], ["Sieve tubes thicken their walls to resist pressure", "Not supported by the live data."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-q-methods", "t": 3, "plate": "sieve", "b": "MEASURED", "src": ["10.1093/treephys/tpv020", "10.1111/j.1365-3040.2006.01544.x"], "q": "Trees average 56 cm h⁻¹ (about 0.16 mm s⁻¹); MRI in herbs and poplar gave 0.25 to 0.40 mm s⁻¹. Do trees move sugar more slowly than herbs?", "o": [["Not from these numbers alone: tracer fronts and MRI measure different things, and the species differ", "Right. Compare like with like before ranking."], ["Yes, clearly", "Different methods; the comparison is not clean."], ["No, trees are faster", "Nothing here shows that."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-q-kelp", "t": 3, "plate": "sieve", "b": "OPEN QUESTION", "src": ["10.1093/aob/mcw007"], "q": "A textbook says reversing the pressure reverses phloem flow, as Münch predicts. What is the evidence?", "o": [["Shown in bull kelp; the authors state no such evidence exists yet for land plants", "Right. A prediction that has been tested in kelp is still open for land plants."], ["Shown in every plant tested", "Only kelp, so far."], ["Disproven", "Kelp supports it; land plants are untested."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-q-cond", "t": 3, "plate": "sieve", "b": "MEASURED", "src": ["10.1105/tpc.109.070094"], "q": "Across five species, sieve tubes with higher conductivity did not carry faster sap (MRI). What does that tell you?", "o": [["Speed depends on the pressure gradient as well; a plant with wider tubes may run a smaller gradient", "Right. Conductivity alone does not predict speed."], ["Hagen-Poiseuille is wrong", "The equation needs the gradient too; the data do not contradict it."], ["MRI cannot measure phloem", "It can; the result is about the plants."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "sv-q-opt", "t": 3, "plate": "sieve", "b": "MODEL", "src": ["10.1098/rsif.2013.0055"], "q": "A flow model predicts the best sap sugar is 23.5 %; measured sap averages 18.2 %, and 21.1 % in active loaders. Is phloem sap “optimal”?", "o": [["Close to the model optimum, especially in active loaders, but a model that assumes pressure independent of concentration cannot prove it", "Right. Agreement is support, not proof."], ["Yes, exactly optimal", "18.2 is not 23.5."], ["No, plants ignore viscosity", "The closeness suggests viscosity matters."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sieve", "where": "Sugar II, the Sieve tube"}, {"id": "xp-k-source", "t": 1, "plate": "xylem", "b": "MODEL", "src": ["10.1111/pce.12004"], "q": "Where does the sieve tube near a source leaf get the water that builds its pressure?", "o": [["From the xylem next door, drawn in by the sugar it holds", "Right. Water moves in until the water potential matches the xylem."], ["From the air, through the stomata", "Water vapour leaves through stomata; it does not fill the phloem."], ["It makes it by breaking down sugar", "Respiration makes a little water, nowhere near enough to drive flow."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-k-counter", "t": 1, "plate": "xylem", "b": "MEASURED", "src": ["10.1111/j.1365-3040.2006.01544.x"], "q": "What happens to the phloem water once the sap has delivered its sugar at the sink?", "o": [["It leaves the sieve tube and goes back up in the xylem", "Right. The Münch counterflow: water circulates between the two pipes."], ["It stays in the sink forever", "Some is used, but most returns to the xylem."], ["It evaporates from the root", "Roots do not evaporate the phloem water."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-k-rays", "t": 1, "plate": "xylem", "b": "MEASURED", "src": ["10.1093/treephys/tpv058"], "q": "Which living cells run across a stem and connect inner bark and xylem?", "o": [["Ray cells", "Right. Rays carry water and sugar sideways and make the two pipes one network."], ["Guard cells", "Guard cells border stomata in leaves."], ["Root hairs", "Root hairs are on the root surface."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-k-dry", "t": 1, "plate": "xylem", "b": "MODEL", "src": ["10.1111/pce.12004", "10.1111/pce.13017"], "q": "The xylem water potential becomes more negative at midday. In the model, the turgor at the source end of the sieve tube:", "o": [["Drops by the same amount", "Right. P = Ψx + Π: each 0.1 MPa off Ψx is 0.1 MPa off P."], ["Rises, because the xylem pulls harder", "The xylem pulls water away from the sieve tube."], ["Does not change", "They share water, so they are tied."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-k-bark", "t": 1, "plate": "xylem", "b": "MEASURED", "src": ["10.1111/pce.13017"], "q": "In Scots pine and Norway spruce, what did inner bark osmolality track closely?", "o": [["The xylem water potential", "Right. The phloem side follows the water status of the xylem."], ["Air temperature only", "Not what was found; the xylem link was the strong one."], ["Nothing; it stayed constant", "It changed, in step with xylem water potential."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-k-small", "t": 1, "plate": "xylem", "b": "MEASURED", "src": ["10.1111/nph.12973"], "q": "In Norway spruce, how well did the phloem conduct compared with the outer ring of xylem?", "o": [["About 2 %", "Right. A small pipe beside a big one; the tree also made ten times more xylem than phloem."], ["About the same", "The xylem conducts far more."], ["About ten times more", "It is the other way round."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-u-stop", "t": 2, "plate": "xylem", "b": "DERIVED", "src": ["10.1111/pce.12004", "10.7554/eLife.15341"], "q": "Sap Π = 1.59 MPa, sink turgor 0.59 MPa. At what xylem water potential does the push from source to sink vanish in the model?", "o": [["−1.00 MPa", "Right. Ψx + 1.59 = 0.59 gives Ψx = −1.00 MPa."], ["−2.18 MPa", "That adds the sink turgor instead of subtracting it."], ["−0.59 MPa", "That forgets the osmotic pressure."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-u-noon", "t": 2, "plate": "xylem", "b": "MODEL", "src": ["10.1111/pce.12004"], "q": "Morning: Ψx −0.50 MPa, source turgor 1.09 MPa, sink 0.59 MPa. Midday Ψx −0.80 MPa, same sap. What fraction of the push is left?", "o": [["About 40 %", "Right. Push falls from 0.50 to 0.20 MPa: 0.20 ÷ 0.50."], ["About 60 %", "That is the share lost, not the share left."], ["About 74 %", "That compares turgor, not push; the push is turgor minus sink."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-u-ratio", "t": 2, "plate": "xylem", "b": "MEASURED", "src": ["10.1111/j.1365-3040.2006.01544.x"], "q": "At night in tobacco, phloem flow was 0.55 of xylem flow. If the xylem carried 10 units of water, how many rode down in the phloem?", "o": [["5.5 units", "Right. 0.55 × 10."], ["0.55 units", "The ratio applies to the 10 units."], ["18 units", "That divides instead of multiplying."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-u-sugar", "t": 2, "plate": "xylem", "b": "MODEL", "src": ["10.1111/pce.12004"], "q": "A leaf with dry xylem loads more sugar. What does it gain, and what does it pay?", "o": [["More osmotic pull wins water back and raises the push; the sap thickens, so each extra percent buys less speed", "Right. In 3.2 the gap to the dashed line is the price of thickness."], ["Sugar thins the sap, so it gains twice", "Sugar thickens sap."], ["Sugar has no effect on water", "Sugar is the osmotic pull."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-u-radial", "t": 2, "plate": "xylem", "b": "MODEL", "src": ["10.1093/plphys/kiac231"], "q": "A model lets water enter the sieve tube along its whole length. Sugar transport rose about 40 % in active loaders. Why?", "o": [["The extra water dilutes the sap and lowers its viscosity along the way", "Right. Thinner sap, easier flow."], ["The water carries extra sugar from the xylem", "Xylem sap carries little sugar."], ["It raises the sink turgor", "The gain comes from lower viscosity."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-u-trees", "t": 2, "plate": "xylem", "b": "MEASURED", "src": ["10.1104/pp.111.184820"], "q": "Across 45 species, which plants had high leaf sugar and high leaf osmolality?", "o": [["Trees and the few herbs that load passively", "Right. They also had low whole plant hydraulic conductance."], ["Herbs that load actively", "They had high conductance and low leaf sugar."], ["All plants equally", "The groups differed clearly."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-q-model", "t": 3, "plate": "xylem", "b": "MODEL", "src": ["10.1111/pce.12004", "10.1111/nph.12224"], "q": "This page lets the sieve tube match the xylem water potential instantly. What does that leave out?", "o": [["The finite radial conductance between xylem and phloem and the buffering of bark storage, so real turgor lags the xylem", "Right. Dendrometer signals show the lag and its temperature dependence."], ["Gravity, which is the main term in all plants", "Gravity matters in tall stems but is not the main omission here."], ["Nothing; the coupling is exact", "It is a model assumption."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-q-stomata", "t": 3, "plate": "xylem", "b": "MODEL", "src": ["10.1093/treephys/tpx011", "10.1111/pce.12004"], "q": "Models in which stomata open just enough to keep phloem transport going reproduce observed gas exchange. Does that prove stomata are set by the phloem?", "o": [["No; it shows the idea is consistent with the data, and other optimisation targets may fit too", "Right. Fit is support, not proof."], ["Yes, it proves it", "A model fit cannot exclude rival explanations."], ["No; stomata have nothing to do with phloem", "Transpiration lowers Ψx, which does affect phloem turgor."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-q-tall", "t": 3, "plate": "xylem", "b": "OPEN QUESTION", "src": ["10.1038/s41477-017-0064-y", "10.1038/nplants.2017.32"], "q": "Most trees load passively. How might they still push sugar tens of metres?", "o": [["Lower sieve tube resistance with height, plus a source pressure that passive loading can still build, are proposed; it is still argued", "Right. An open question with partial answers."], ["They pump sugar with ATP all along the stem", "No evidence for that along the path."], ["Gravity carries the sugar down", "Sugar also goes up to young leaves and fruit."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-q-gymno", "t": 3, "plate": "xylem", "b": "MEASURED", "src": ["10.1111/nph.12973"], "q": "Phloem conductivity was about 2 % of xylem in Norway spruce. Can you apply that number to almond?", "o": [["Not directly: spruce is a conifer with different conducting cells; it shows the order of magnitude only", "Right. Name the species before you borrow a number."], ["Yes, all trees are the same", "Conifers and angiosperms differ in phloem anatomy."], ["Yes, almond is a conifer", "Almond is a flowering plant."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-q-ratio", "t": 3, "plate": "xylem", "b": "MEASURED", "src": ["10.1111/j.1365-3040.2006.01544.x"], "q": "Night phloem to xylem flow ratios: tomato 0.04, tobacco 0.55. Why might the share be smaller in the day?", "o": [["Xylem flow rises with transpiration in the day, so the same phloem flow is a smaller share", "Right. The denominator grows."], ["The phloem stops in daylight", "Phloem moves day and night."], ["MRI cannot see in daylight", "MRI works regardless of light."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "xp-q-sap", "t": 3, "plate": "xylem", "b": "MODEL", "src": ["10.1098/rsif.2013.0055"], "q": "In 3.2 a drier xylem needs more sugar before any flow starts. What would you need to test that in plants?", "o": [["Sap concentration, viscosity and speed measured in the same plants across a range of xylem water potentials", "Right. Measure all three together."], ["Only the leaf sugar", "Speed and viscosity are needed too."], ["Nothing, the model is enough", "A model prediction is a hypothesis."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#xylem", "where": "Sugar III, Xylem meets phloem"}, {"id": "sk-k-root", "t": 1, "plate": "sinks", "b": "MEASURED", "src": ["10.7554/eLife.24125"], "q": "In Arabidopsis root tips, how does sugar leave the protophloem?", "o": [["Through plasmodesmata, by mass flow plus diffusion", "Right. Convective unloading through funnel plasmodesmata."], ["Only by membrane transporters into the cell walls", "That is the apple fruit route, not the root tip."], ["It does not leave; roots store it in the phloem", "It is unloaded into the pericycle and on."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-k-funnel", "t": 1, "plate": "sinks", "b": "MEASURED", "src": ["10.1111/tpj.15697"], "q": "What shape are the plasmodesmata between protophloem and phloem pole pericycle in root tips?", "o": [["Funnel shaped (conical)", "Right. Found in five eudicot and two monocot species."], ["Straight cylinders", "Most textbook drawings show those; these are funnels."], ["There are no plasmodesmata there", "They are the route."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-k-batch", "t": 1, "plate": "sinks", "b": "MEASURED", "src": ["10.7554/eLife.24125"], "q": "Large proteins leaving the protophloem in a root tip:", "o": [["Leave in pulses and stay in the phloem pole pericycle", "Right. “Batch unloading”."], ["Spread freely to every cell", "That is what small solutes do."], ["Never leave", "They do, in pulses."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-k-apple", "t": 1, "plate": "sinks", "b": "MEASURED", "src": ["10.1104/pp.103.036632"], "q": "In apple fruit flesh, why does unloading need a step through the cell wall space?", "o": [["The sieve element companion cell complex is symplasmically isolated", "Right. No open plasmodesmata out of the complex."], ["Apple fruit has no phloem", "It does; the bundles run through the flesh."], ["Sugar is too large for plasmodesmata", "Isolation, not size, is the reason here."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-k-sink", "t": 1, "plate": "sinks", "b": "MODEL", "src": ["10.7554/eLife.15341"], "q": "In the pressure flow picture, a sink pulls more sugar when it:", "o": [["Keeps the turgor at its end of the tube lower, by unloading faster", "Right. A bigger pressure difference, more flow."], ["Raises its turgor", "That reduces the push toward it."], ["Makes its own sugar", "Then it is becoming a source."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-k-sorb", "t": 1, "plate": "sinks", "b": "MEASURED", "src": ["10.1093/plphys/kiad226"], "q": "In apple, sorbitol arriving in a sink also:", "o": [["Acts as a signal that switches on its own breakdown genes", "Right. Through SnRK1 and bZIP39."], ["Blocks the phloem", "No evidence for that."], ["Turns into starch in the phloem", "Sorbitol is broken down in sink cells."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-u-share", "t": 2, "plate": "sinks", "b": "MODEL", "src": ["10.7554/eLife.15341"], "q": "Source 1.09 MPa. Fruit at 0.59 MPa, 1 m away; root at 0.59 MPa, 2 m away. Same tubes. Fruit flow ÷ root flow?", "o": [["2", "Right. Same ΔP, half the length: twice the gradient."], ["0.5", "The shorter path gets more, not less."], ["1", "Path length matters."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-u-fill", "t": 2, "plate": "sinks", "b": "MODEL", "src": ["10.7554/eLife.15341"], "q": "Source 1.09 MPa. A fruit drops its turgor from 0.59 to 0.29 MPa. Its pressure difference grows by what factor?", "o": [["1.6 times (0.50 to 0.80 MPa)", "Right. And its flow rises in step."], ["2 times", "Check: 1.09 − 0.29 = 0.80, against 0.50."], ["It does not change", "The sink end is lower, so the difference grows."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-u-full", "t": 2, "plate": "sinks", "b": "MODEL", "src": ["10.7554/eLife.15341"], "q": "A full fruit holds 1.10 MPa while the source is at 1.09 MPa. What flows to it in the model?", "o": [["Nothing: the sink is at or above the source", "Right. No pressure difference, no flow (and no backflow in this model)."], ["A little, because it is close", "Distance cannot make up for a zero push."], ["Sugar flows from the fruit back to the leaf", "Reversal is not allowed in this model and is unproven in land plants."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-u-funnel", "t": 2, "plate": "sinks", "b": "MODEL", "src": ["10.1111/tpj.15697"], "q": "Why might a funnel shaped pore matter for unloading?", "o": [["It has much lower resistance to flow and diffusion than a cylinder of the same narrowest width", "Right. Shown by model calculations on the measured shapes."], ["It filters out all sugar", "Sugar passes freely."], ["It pumps sugar", "Pores do not pump."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-u-silence", "t": 2, "plate": "sinks", "b": "MEASURED", "src": ["10.1073/pnas.0605873103"], "q": "Silencing sorbitol synthesis in apple cut the sorbitol to sucrose ratio by about 90 % in leaves. A ratio of 4 would fall to about:", "o": [["0.4", "Right. 10 % of 4."], ["3.6", "That is a 10 % drop, not a 90 % drop."], ["0", "About 90 %, not all of it."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-u-apo", "t": 2, "plate": "sinks", "b": "MEASURED", "src": ["10.1104/pp.102.016725"], "q": "Sour cherry sorbitol transporters are H⁺ coupled. What does that suggest about fruit unloading?", "o": [["A step through the cell wall space with uptake driven by the proton gradient", "Right. Energy is spent at the sink."], ["Purely passive flow through plasmodesmata", "Transporters point to a membrane step."], ["That the fruit loads sugar into the phloem", "A fruit is a sink."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-q-turgor", "t": 3, "plate": "sinks", "b": "MODEL", "src": ["10.1111/nph.17795"], "q": "A model tested on girdling and drought data in four tree species fits best with turgor regulated unloading. What would weaken that conclusion?", "o": [["A direct measurement in which sinks take more sugar at the same turgor when sugar concentration rises", "Right. That would favour sugar regulation."], ["Another model fit that agrees", "Agreement adds support; it does not weaken it."], ["Finding funnel plasmodesmata", "They fit either mechanism."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-q-manifold", "t": 3, "plate": "sinks", "b": "OPEN QUESTION", "src": ["10.7554/eLife.15341"], "q": "Small morning glory plants made only enough pressure for flow. Why does that argue against a high pressure manifold?", "o": [["A manifold needs pressure held high everywhere with sinks opening taps; these plants had no spare pressure", "Right. So unloading must be very conductive or use energy."], ["Because morning glory has no sinks", "It has roots and fruits."], ["Because pressure flow is wrong", "The same data support pressure flow."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-q-almond", "t": 3, "plate": "sinks", "b": "OPEN QUESTION", "src": ["10.1104/pp.103.036632", "10.1104/pp.102.016725"], "q": "Apple fruit unloads with an apoplastic step and cherry transporters point the same way. Can you say almond does too?", "o": [["Not yet: no almond study was retrieved; it is a reasonable hypothesis from close relatives", "Right. Name it a hypothesis."], ["Yes, all Rosaceae are the same", "Relatives differ; apple and peach even load differently."], ["No, almond is proven symplastic", "There is no almond study either way."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-q-model", "t": 3, "plate": "sinks", "b": "MODEL", "src": ["10.1111/pce.12004"], "q": "The three sink model holds the source turgor fixed. What happens in a real plant when one sink pulls much harder?", "o": [["The source turgor drops a little, so other sinks lose flow outright, not just share", "Right. The fixed source is a simplification."], ["Nothing changes at the source", "Flow out of the source must be supplied."], ["All sinks gain", "The supply is shared."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-q-proteins", "t": 3, "plate": "sinks", "b": "MEASURED", "src": ["10.7554/eLife.24125"], "q": "Solutes leave the protophloem freely, proteins leave in pulses and stay in the pericycle. What does that suggest about the pericycle?", "o": [["It sorts what leaves the phloem and helps regulate unloading", "Right. The authors give it a major regulatory role."], ["It is a dead end with no role", "The data argue for a role."], ["It loads sugar back into the phloem", "Not what was observed."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "sk-q-young", "t": 3, "plate": "sinks", "b": "ILLUSTRATIVE", "src": [], "q": "In 4.1 the young leaf takes the largest share at equal sink turgor. Is that a measured result?", "o": [["No: its path length and turgor are teaching values, and no growing leaf unloading paper was retrieved for this page", "Right. The model shows a principle, not a measurement."], ["Yes, young leaves always win", "Nothing measured here says so."], ["Yes, from Ross-Elliott et al. 2017", "That paper studied root tips."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#sinks", "where": "Sugar IV, Sinks"}, {"id": "st-k-beech", "t": 1, "plate": "stress", "b": "MEASURED", "src": ["10.1093/treephys/tpy122"], "q": "Mature beech under three years of throughfall exclusion: phloem speed went from 20.7 to 11.0 cm h⁻¹. That is:", "o": [["Slower by about half (47 %)", "Right. And new sugar stayed in the leaves longer."], ["Faster", "It fell."], ["Unchanged", "It nearly halved."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-k-two", "t": 1, "plate": "stress", "b": "MODEL", "src": ["10.1093/jxb/ert467"], "q": "Theory gives drought two ways to stop the phloem. Which two?", "o": [["Loss of sieve tube turgor, or sap too viscous to move", "Right. Turgor collapse or a viscous jam."], ["Air bubbles and frost", "Those are xylem problems."], ["Too many stomata and too much light", "Not phloem failure modes."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-k-K", "t": 1, "plate": "stress", "b": "MEASURED", "src": ["10.1093/treephys/tpv090"], "q": "In field eucalypts, carbon moved down the trunk about twice as fast with:", "o": [["Potassium", "Right. An osmolyte that adds push."], ["Shade", "Not the treatment."], ["Less water", "Rain exclusion had little effect, except in one tree."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-k-recover", "t": 1, "plate": "stress", "b": "MEASURED", "src": ["10.1111/nph.17815"], "q": "Pine seedlings after heat alone moved new carbon to the roots in 7.1 h; after drought plus heat:", "o": [["13.8 h, about twice as long", "Right. Recovery depends on the phloem."], ["3.5 h", "It was slower, not faster."], ["The same", "It nearly doubled."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-k-callose", "t": 1, "plate": "stress", "b": "MEASURED", "src": ["10.1105/tpc.109.070094"], "q": "Within minutes of injury, what can close sieve plate pores?", "o": [["Callose", "Right. A wound seal."], ["Suberin", "Suberin seals root walls, not plate pores."], ["Starch", "A store, not a seal."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-k-few", "t": 1, "plate": "stress", "b": "MEASURED", "src": ["10.1093/treephys/tpy153"], "q": "A review of tree phloem under drought found:", "o": [["Responses from none to slowdown to possible disruption, from too few species", "Right. Not every tree slows."], ["Every tree stops its phloem in drought", "Some show no response."], ["Drought always speeds the phloem", "Not supported."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-u-collapse", "t": 2, "plate": "stress", "b": "DERIVED", "src": ["10.1111/pce.12004", "10.7554/eLife.15341"], "q": "Ψx −1.40 MPa, sap Π 1.59 MPa, sink 0.59 MPa. What is the push?", "o": [["None: 0.19 MPa at the source is below the sink", "Right. Turgor collapse in the model."], ["0.19 MPa", "That is the source turgor, not the push."], ["1.19 MPa", "Check the sign of Ψx."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-u-adjust", "t": 2, "plate": "stress", "b": "DERIVED", "src": ["10.1111/pce.12004"], "q": "Same drought (Ψx −1.40 MPa, sink 0.59 MPa). What Π must the sap reach just to get a push at all?", "o": [["More than 1.99 MPa", "Right. Π > P_sink − Ψx = 0.59 + 1.40."], ["More than 0.81 MPa", "That subtracts instead of adding."], ["Any Π above zero", "The xylem pull must be beaten first."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-u-mrt", "t": 2, "plate": "stress", "b": "MEASURED", "src": ["10.1093/treephys/tpy122"], "q": "Beech leaf residence time of new sugar: 32.1 h control, 46.9 h drought. By what percentage did it rise?", "o": [["About 46 %", "Right. (46.9 − 32.1) ÷ 32.1."], ["About 15 %", "That is the difference in hours."], ["About 32 %", "Divide by the control, 32.1."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-u-heat", "t": 2, "plate": "stress", "b": "DERIVED", "src": ["10.1111/nph.17815"], "q": "In the model, raising the temperature from 25 to 38 °C speeds the sap. Why, and what does that tell you about the model?", "o": [["Warm water is thinner; the model has no heat damage, so it cannot show the slower recovery seen in real plants", "Right. Know what a model leaves out."], ["Heat raises turgor greatly", "Π rises only a little with T."], ["Heat is good for the phloem", "Measured recovery after drought plus heat was slower."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-u-K", "t": 2, "plate": "stress", "b": "MEASURED", "src": ["10.1038/s41477-022-01098-x"], "q": "Why could potassium help a droughted phloem more than extra sugar?", "o": [["It adds osmotic push without thickening the sap as much as sugar does", "Right. Push without the viscous penalty."], ["Potassium is a sugar", "It is an ion."], ["Potassium blocks the xylem", "Not its role."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-u-eps", "t": 2, "plate": "stress", "b": "MEASURED", "src": ["10.1093/treephys/tpv090"], "q": "Eucalypt trunk carbon velocity: 0.20 to 0.82 m h⁻¹. In cm h⁻¹ that is:", "o": [["20 to 82 cm h⁻¹", "Right. 1 m = 100 cm."], ["2 to 8.2 cm h⁻¹", "Ten times too small."], ["200 to 820 cm h⁻¹", "Ten times too large."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-q-which", "t": 3, "plate": "stress", "b": "OPEN QUESTION", "src": ["10.1093/jxb/ert467", "10.1111/nph.13461"], "q": "Evidence favours turgor collapse in plants that keep leaf water potential steady. Why might plants that let it fall far behave differently?", "o": [["They can load more osmolytes as they dry, keeping turgor up until viscosity limits; whether they do is open", "Right. A hypothesis to test."], ["They have no phloem", "All vascular plants do."], ["Their xylem never dries", "It dries more, not less."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-q-confound", "t": 3, "plate": "stress", "b": "MEASURED", "src": ["10.1093/treephys/tpy122"], "q": "Droughted beech moved sugar 47 % slower. Name a confound before you blame the phloem.", "o": [["Lower photosynthesis means less sugar loaded, so slower export could come from less cargo, not less push", "Right. Measure assimilation and leaf sugar too."], ["Beech is not a tree", "It is."], ["The velocity was measured in the xylem", "It was phloem transport."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-q-three", "t": 3, "plate": "stress", "b": "MODEL", "src": ["10.1111/nph.13461"], "q": "A 170 species model finds phloem failure when photosynthesis is not very sensitive to drought but growth is. Why does that combination point to the phloem?", "o": [["Sugar is still made but cannot be used or moved fast enough, so transport becomes the limit", "Right. Neither starvation nor hydraulics alone."], ["It means the xylem fails first", "That is the hydraulic route."], ["It means the plant starves", "Photosynthesis is still running."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-q-anat", "t": 3, "plate": "stress", "b": "MEASURED", "src": ["10.1111/nph.70578"], "q": "Across 188 woody angiosperms, sieve element diameter tracked water availability. What would you need before calling that an adaptation to drought?", "o": [["A test that separates it from size and distance to the stem tip, which mainly set conduit size, and from shared ancestry", "Right. Correlation across species has confounds."], ["Nothing; the correlation proves it", "Correlation is not mechanism."], ["A single species measured once", "That cannot speak to a pattern across species."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-q-recover", "t": 3, "plate": "stress", "b": "OPEN QUESTION", "src": ["10.1111/nph.17815", "10.1093/treephys/tpy153"], "q": "Recovery took about twice as long after drought plus heat in pine seedlings. Can you say the same for mature trees?", "o": [["No; seedlings in one species are a start, and tree data cover few species", "Right. It is an open question."], ["Yes, seedlings and trees are the same", "Size and storage differ greatly."], ["Yes, all conifers recover the same way", "Not shown."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}, {"id": "st-q-map", "t": 3, "plate": "stress", "b": "MODEL", "src": ["10.1093/jxb/ert467"], "q": "On the 5.1 map, the grey zone grows when the sink turgor is raised. Why?", "o": [["The source must beat a higher sink pressure, so more of the dry, low sugar corner has no push", "Right. Ψx + Π must exceed P_sink."], ["A higher sink turgor thickens the sap", "Viscosity depends on sugar and temperature."], ["The map is wrong", "It follows the model rule."]], "a": 0, "module": "phloem", "stop": "phloem", "href": "phloem/index.html#stress", "where": "Sugar V, Under stress"}], "sources": {"10.1073/pnas.0902279106": "Rennie & Turgeon (2009) PNAS 106: 14162 to 14167", "10.1126/science.1213351": "Chen et al. (2012) Science 335: 207 to 211", "10.1007/s00709-010-0240-7": "Davidson, Keller & Turgeon (2011) Protoplasma 248: 153 to 163", "10.1104/pp.102.016725": "Gao et al. (2003) Plant Physiol 131: 1566 to 1575", "10.1007/s00425-007-0682-0": "Nadwodnik & Lohaus (2008) Planta 227: 1079 to 1089", "10.1111/pce.12004": "Nikinmaa et al. (2013) Plant Cell Environ 36: 655 to 669", "10.1104/pp.114.245845": "Zhang et al. (2014) Plant Physiol 166: 306 to 313", "10.7554/eLife.15341": "Knoblauch et al. (2016) eLife 5: e15341", "10.1104/pp.108.134791": "Reidel et al. (2009) Plant Physiol 149: 1601 to 1608", "10.1073/pnas.0605873103": "Teo et al. (2006) PNAS 103: 18842 to 18847", "10.1104/pp.111.184820": "Fu et al. (2011) Plant Physiol 157: 1518 to 1527", "10.1038/nplants.2017.32": "Comtet et al. (2017) Nat Plants 3: 17032", "10.1038/s41477-022-01098-x": "Babst et al. (2022) Nat Plants 8: 171 to 180", "10.1073/pnas.2112755119": "Liu et al. (2022) PNAS 119: e2112755119", "10.1104/pp.106.085803": "Martens et al. (2006) Plant Physiol 142: 471 to 480", "10.1105/tpc.109.070094": "Mullendore et al. (2010) Plant Cell 22: 579 to 593", "10.1111/j.1365-3040.2006.01544.x": "Windt et al. (2006) Plant Cell Environ 29: 1715 to 1729", "10.1105/tpc.111.093179": "Froelich et al. (2011) Plant Cell 23: 4428 to 4445", "10.3389/fpls.2012.00151": "Jensen et al. (2012) Front Plant Sci 3: 151", "10.1093/treephys/tpv020": "Liesche et al. (2015) Tree Physiol 35: 376 to 386", "10.1093/treephys/tpy122": "Hesse et al. (2019) Tree Physiol 39: 192 to 200", "10.1111/tpj.14665": "Knoblauch et al. (2020) Plant J 102: 797 to 808", "10.1093/aob/mcw007": "Knoblauch et al. (2016) Ann Bot 117: 599 to 606", "10.1098/rsif.2013.0055": "Jensen, Savage & Holbrook (2013) J R Soc Interface 10: 20130055", "10.1093/treephys/tpv058": "Pfautsch, Hölttä & Mencuccini (2015) Tree Physiol 35: 706 to 722", "10.1111/pce.13017": "Paljakka et al. (2017) Plant Cell Environ 40: 2160 to 2173", "10.1111/nph.12973": "Jyske & Hölttä (2015) New Phytol 205: 102 to 115", "10.1093/plphys/kiac231": "Nakad et al. (2022) Plant Physiol 189: 2061 to 2071", "10.1111/nph.12224": "Mencuccini et al. (2013) New Phytol 198: 1143 to 1154", "10.1093/treephys/tpx011": "Hölttä et al. (2017) Tree Physiol 37: 851 to 868", "10.1038/s41477-017-0064-y": "Savage et al. (2017) Nat Plants 3: 965 to 972", "10.7554/eLife.24125": "Ross-Elliott et al. (2017) eLife 6: e24125", "10.1111/tpj.15697": "Ostermeyer et al. (2022) Plant J 110: 707 to 719", "10.1104/pp.103.036632": "Zhang et al. (2004) Plant Physiol 135: 574 to 586", "10.1093/plphys/kiad226": "Meng et al. (2023) Plant Physiol 192: 2123 to 2142", "10.1111/nph.17795": "Dewar et al. (2022) New Phytol 233: 639 to 654", "10.1093/jxb/ert467": "Sevanto (2014) J Exp Bot 65: 1751 to 1759", "10.1093/treephys/tpv090": "Epron et al. (2016) Tree Physiol 36: 6 to 21", "10.1111/nph.17815": "Rehschuh et al. (2022) New Phytol 233: 687 to 704", "10.1093/treephys/tpy153": "Salmon et al. (2019) Tree Physiol 39: 173 to 191", "10.1111/nph.13461": "Mencuccini et al. (2015) New Phytol 208: 396 to 409", "10.1111/nph.70578": "Wang et al. (2025) New Phytol 248: 2316 to 2330"}, "plates": {"source": "Sugar I, the Source leaf", "sieve": "Sugar II, the Sieve tube", "xylem": "Sugar III, Xylem meets phloem", "sinks": "Sugar IV, Sinks", "stress": "Sugar V, Under stress"}};
